-- sql-agent-kit 示例数据库（MySQL）
-- 由 scripts/init_db.py 生成，共 9 张表
-- 数据基准日：2026-09-21（订单覆盖此前 12 个月）
-- 导入：mysql -u root -p your_database < scripts/init_db.sql

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` VARCHAR(50) NOT NULL COMMENT '用户姓名',
  `email` VARCHAR(120) NOT NULL COMMENT '用户邮箱地址',
  `phone` VARCHAR(20) NULL COMMENT '用户手机号码',
  `created_at` DATETIME NOT NULL COMMENT '账号注册时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_users_email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户基本信息表';

DROP TABLE IF EXISTS `categories`;
CREATE TABLE `categories` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` VARCHAR(50) NOT NULL COMMENT '分类名称',
  `parent_id` BIGINT NULL COMMENT '父级分类ID，为空表示顶级分类',
  `created_at` DATETIME NOT NULL COMMENT '分类创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_categories_parent_id` (`parent_id`),
  CONSTRAINT `fk_categories_parent_id` FOREIGN KEY (`parent_id`) REFERENCES `categories` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='商品分类表，支持树形层级结构';

DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` VARCHAR(120) NOT NULL COMMENT '商品名称',
  `category_id` BIGINT NOT NULL COMMENT '所属商品分类ID',
  `price` DECIMAL(12,2) NOT NULL COMMENT '商品销售价格',
  `stock` INT NOT NULL DEFAULT 0 COMMENT '商品当前库存数量',
  `created_at` DATETIME NOT NULL COMMENT '商品创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_products_category_id` (`category_id`),
  CONSTRAINT `fk_products_category_id` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='商品信息表';

DROP TABLE IF EXISTS `orders`;
CREATE TABLE `orders` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` BIGINT NOT NULL COMMENT '下单用户ID',
  `status` VARCHAR(20) NOT NULL COMMENT '订单状态',
  `total_amount` DECIMAL(12,2) NOT NULL COMMENT '订单总金额',
  `created_at` DATETIME NOT NULL COMMENT '订单创建时间',
  `updated_at` DATETIME NOT NULL COMMENT '订单最后更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_orders_user_id` (`user_id`),
  CONSTRAINT `fk_orders_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单主表，记录用户订单基础信息';

DROP TABLE IF EXISTS `order_items`;
CREATE TABLE `order_items` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `order_id` BIGINT NOT NULL COMMENT '关联的订单ID',
  `product_id` BIGINT NOT NULL COMMENT '关联的商品ID',
  `quantity` INT NOT NULL COMMENT '购买商品数量',
  `unit_price` DECIMAL(12,2) NOT NULL COMMENT '购买时的商品单价',
  PRIMARY KEY (`id`),
  KEY `idx_order_items_order_id` (`order_id`),
  KEY `idx_order_items_product_id` (`product_id`),
  CONSTRAINT `fk_order_items_order_id` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`),
  CONSTRAINT `fk_order_items_product_id` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单明细表，记录订单中包含的商品信息';

DROP TABLE IF EXISTS `ad_campaigns`;
CREATE TABLE `ad_campaigns` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `channel` VARCHAR(30) NOT NULL COMMENT '广告投放渠道',
  `campaign` VARCHAR(100) NOT NULL COMMENT '广告活动名称',
  `start_date` DATE NOT NULL COMMENT '投放开始日期',
  `end_date` DATE NOT NULL COMMENT '投放结束日期',
  `budget` DECIMAL(12,2) NOT NULL COMMENT '广告预算金额',
  `spend` DECIMAL(12,2) NOT NULL COMMENT '广告实际花费金额',
  `impressions` BIGINT NOT NULL COMMENT '广告曝光量',
  `clicks` INT NOT NULL COMMENT '广告点击量',
  `orders` INT NOT NULL COMMENT '广告带来的订单转化数',
  `revenue` DECIMAL(12,2) NOT NULL COMMENT '广告带来的收入金额',
  `created_at` DATETIME NOT NULL COMMENT '记录创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='广告投放活动效果统计表';

DROP TABLE IF EXISTS `user_behavior`;
CREATE TABLE `user_behavior` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` BIGINT NOT NULL COMMENT '操作用户ID',
  `session_id` VARCHAR(64) NOT NULL COMMENT '用户会话ID',
  `action` VARCHAR(30) NOT NULL COMMENT '用户行为类型',
  `product_id` BIGINT NULL COMMENT '操作关联的商品ID，无关联商品时为空',
  `page` VARCHAR(120) NULL COMMENT '访问的页面路径',
  `duration_s` INT NULL COMMENT '页面停留时长（秒）',
  `device` VARCHAR(20) NULL COMMENT '访问设备类型',
  `created_at` DATETIME NOT NULL COMMENT '行为发生时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_behavior_user_id` (`user_id`),
  KEY `idx_user_behavior_product_id` (`product_id`),
  CONSTRAINT `fk_user_behavior_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_user_behavior_product_id` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户行为日志表，记录用户在端上的操作轨迹';

DROP TABLE IF EXISTS `product_reviews`;
CREATE TABLE `product_reviews` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `product_id` BIGINT NOT NULL COMMENT '评价的商品ID',
  `user_id` BIGINT NOT NULL COMMENT '评价的用户ID',
  `order_id` BIGINT NULL COMMENT '评价关联的订单ID',
  `rating` INT NOT NULL COMMENT '评分等级（1-5星）',
  `tag` VARCHAR(30) NULL COMMENT '评价标签',
  `content` TEXT NULL COMMENT '评价具体内容，为空表示未填写文字评价',
  `created_at` DATETIME NOT NULL COMMENT '评价创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_product_reviews_product_id` (`product_id`),
  KEY `idx_product_reviews_user_id` (`user_id`),
  KEY `idx_product_reviews_order_id` (`order_id`),
  CONSTRAINT `fk_product_reviews_product_id` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`),
  CONSTRAINT `fk_product_reviews_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_product_reviews_order_id` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='商品评价表';

DROP TABLE IF EXISTS `inventory_log`;
CREATE TABLE `inventory_log` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `product_id` BIGINT NOT NULL COMMENT '变更的商品ID',
  `change_type` VARCHAR(20) NOT NULL COMMENT '库存变更类型',
  `quantity` INT NOT NULL COMMENT '库存变更数量，正数增加负数减少',
  `stock_after` INT NOT NULL COMMENT '变更后的库存数量',
  `remark` VARCHAR(200) NULL COMMENT '库存变更备注说明',
  `created_at` DATETIME NOT NULL COMMENT '库存变更时间',
  PRIMARY KEY (`id`),
  KEY `idx_inventory_log_product_id` (`product_id`),
  CONSTRAINT `fk_inventory_log_product_id` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='商品库存变更流水表';










SET FOREIGN_KEY_CHECKS = 1;
